export function getAllCoursesFlat() {
  const list = [];
  COURSE_DOMAINS.forEach(domain => {
    domain.courses.forEach(c => {
      list.push({
        ...c,
        domainId: domain.id,
        domainName: domain.name,
        domainShortName: domain.shortName,
        emoji: domain.emoji,
        gradient: domain.gradient,
        accentColor: domain.accentColor
      });
    });
  });
  return list;
}
